∀ {α : Type u_5} {β : Type u_6} {inst : NonAssocSemiring α} {inst_1 : NonAssocSemiring β} {toMonoidHom : α →* β}
  {map_zero' : (↑toMonoidHom).toFun 0 = 0}
  {map_add' : ∀ (x y : α), (↑toMonoidHom).toFun (x + y) = (↑toMonoidHom).toFun x + (↑toMonoidHom).toFun y}
  {toMonoidHom_1 : α →* β} {map_zero'_1 : (↑toMonoidHom_1).toFun 0 = 0}
  {map_add'_1 : ∀ (x y : α), (↑toMonoidHom_1).toFun (x + y) = (↑toMonoidHom_1).toFun x + (↑toMonoidHom_1).toFun y},
  { toMonoidHom := toMonoidHom, map_zero' := map_zero', map_add' := map_add' } =
      { toMonoidHom := toMonoidHom_1, map_zero' := map_zero'_1, map_add' := map_add'_1 } →
    toMonoidHom = toMonoidHom_1

∀ {B : Type u} [inst : CategoryTheory.Bicategory B] {a b c : B} {f : b ⟶ a} {g : c ⟶ a}
  {s t : CategoryTheory.Bicategory.LeftLift f g} (P : s.IsKan) (Q : t.IsKan),
  CategoryTheory.StructuredArrow.Hom.right (P.uniqueUpToIso Q).inv = Q.desc s

∀ {B : Type u} [inst : CategoryTheory.Bicategory B] {a b c : B} {f : a ⟶ b} {g : a ⟶ c}
  {s t : CategoryTheory.Bicategory.LeftExtension f g} (P : s.IsKan) (Q : t.IsKan),
  CategoryTheory.StructuredArrow.Hom.right (P.uniqueUpToIso Q).inv = Q.desc s

∀ {B : Type u} [inst : CategoryTheory.Bicategory B] {a b c : B} {f : b ⟶ a} {g : c ⟶ a}
  {t : CategoryTheory.Bicategory.LeftLift f g} (H : t.IsKan) (s : CategoryTheory.Bicategory.LeftLift f g) {Z : c ⟶ a}
  (h : CategoryTheory.CategoryStruct.comp s.lift f ⟶ Z),
  CategoryTheory.CategoryStruct.comp t.unit
      (CategoryTheory.CategoryStruct.comp (CategoryTheory.Bicategory.whiskerRight (H.desc s) f) h) =
    CategoryTheory.CategoryStruct.comp s.unit h

∀ {B : Type u} [inst : CategoryTheory.Bicategory B] {a b c : B} {f : a ⟶ b} {g : a ⟶ c}
  {s t : CategoryTheory.Bicategory.LeftExtension f g} (P : s.IsKan) (Q : t.IsKan),
  CategoryTheory.StructuredArrow.Hom.right (P.uniqueUpToIso Q).hom = P.desc t

∀ {U : Type u_1} {V : Type u_3} {W : Type u_5} {G : SimpleGraph V} {H : SimpleGraph W} {I : SimpleGraph U}
  (a : V ⊕ W ⊕ U),
  (RelIso.symm SimpleGraph.Iso.sumAssoc) a = Sum.elim (Sum.inl ∘ Sum.inl) (Sum.elim (Sum.inl ∘ Sum.inr) Sum.inr) a

