∀ {U : Type u_1} {U' : Type u_2} {V : Type u_3} {V' : Type u_4} {W : Type u_5} {W' : Type u_6} {G : SimpleGraph V}
  {H : SimpleGraph W} {I : SimpleGraph U} {G' : SimpleGraph V'} {H' : SimpleGraph W'} {I' : SimpleGraph U'}
  (f : G →g G') (g : H →g H') (h : I →g I'),
  (f.sum (g.sum h)).comp SimpleGraph.Iso.sumAssoc.toHom = SimpleGraph.Iso.sumAssoc.toHom.comp ((f.sum g).sum h)

∀ {U : Type u_1} {U' : Type u_2} {V : Type u_3} {V' : Type u_4} {W : Type u_5} {W' : Type u_6} {G : SimpleGraph V}
  {H : SimpleGraph W} {I : SimpleGraph U} {G' : SimpleGraph V'} {H' : SimpleGraph W'} {I' : SimpleGraph U'}
  (f : G ≃g G') (g : H ≃g H') (h : I ≃g I'),
  SimpleGraph.Iso.sumAssoc.comp ((f.sumCongr g).sumCongr h) = (f.sumCongr (g.sumCongr h)).comp SimpleGraph.Iso.sumAssoc

∀ {U : Type u_1} {U' : Type u_2} {V : Type u_3} {V' : Type u_4} {W : Type u_5} {W' : Type u_6} {G : SimpleGraph V}
  {H : SimpleGraph W} {I : SimpleGraph U} {G' : SimpleGraph V'} {H' : SimpleGraph W'} {I' : SimpleGraph U'}
  (f : G ↪g G') (g : H ↪g H') (h : I ↪g I'),
  (f.sum (g.sum h)).comp SimpleGraph.Iso.sumAssoc.toEmbedding =
    SimpleGraph.Iso.sumAssoc.toEmbedding.comp ((f.sum g).sum h)

