∀ {α : Type u_1} {β : Type u_2} [inst : TopologicalSpace α] [inst_1 : TopologicalSpace β] {A : Set (Set α)}
  {F : (s : Set α) → s ∈ A → C(↑s, β)}
  {hF :
    ∀ (s : Set α) (hs : s ∈ A) (t : Set α) (ht : t ∈ A) (x : α) (hxi : x ∈ s) (hxj : x ∈ t),
      (F s hs) ⟨x, hxi⟩ = (F t ht) ⟨x, hxj⟩}
  {hA : ∀ (x : α), ∃ i ∈ A, i ∈ nhds x} {s : Set α} {hs : s ∈ A} (x : ↑s),
  (ContinuousMap.liftCover' A F hF hA) ↑x = (F s hs) x

∀ {α : Type u_1} {β : Type u_2} [inst : TopologicalSpace α] [inst_1 : TopologicalSpace β] {ι : Type u_5} {S : ι → Set α}
  {φ : (i : ι) → C(↑(S i), β)}
  {hφ : ∀ (i j : ι) (x : α) (hxi : x ∈ S i) (hxj : x ∈ S j), (φ i) ⟨x, hxi⟩ = (φ j) ⟨x, hxj⟩}
  {hS : ∀ (x : α), ∃ i, S i ∈ nhds x} {i : ι}, ContinuousMap.restrict (S i) (ContinuousMap.liftCover S φ hφ hS) = φ i

